@* Displays a single task card with title, assignee, priority badge, due date, and move buttons *@

<div class="task-card">
    <div class="task-header">
        <span class="task-title">@Task.Title</span>
        <span class="priority-badge priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    </div>
    <div class="task-details">
        <span class="task-assignee">👤 @Task.Assignee</span>
        <span class="task-due">📅 @Task.DueDate.ToString("MMM dd")</span>
    </div>
    <div class="task-actions">
        @if (CanMoveLeft)
        {
            <button class="btn-move" @onclick="() => OnMoveLeft.InvokeAsync(Task.Id)" disabled="@IsMoving">← Move Left</button>
        }
        @if (CanMoveRight)
        {
            <button class="btn-move" @onclick="() => OnMoveRight.InvokeAsync(Task.Id)" disabled="@IsMoving">Move Right →</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public bool IsMoving { get; set; }
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }
}

@* Inline form for creating a new task within a column *@

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="title" />
    <input type="text" placeholder="Assignee" @bind="assignee" />
    <select @bind="priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" />
    <div class="form-actions">
        <button class="btn-save" @onclick="HandleSave" disabled="@IsSaving">Save</button>
        <button class="btn-cancel" @onclick="HandleCancel" disabled="@IsSaving">Cancel</button>
    </div>
    @if (!string.IsNullOrEmpty(validationError))
    {
        <div class="form-error">@validationError</div>
    }
</div>

@code {
    [Parameter, EditorRequired] public string DefaultStatus { get; set; } = default!;
    [Parameter] public EventCallback<NewTaskRequest> OnSave { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);
    private bool IsSaving;
    private string? validationError;

    public record NewTaskRequest(string Title, string Assignee, string Priority, DateTime DueDate, string Status);

    private async Task HandleSave()
    {
        validationError = null;

        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(assignee))
        {
            validationError = "Title and assignee are required.";
            return;
        }

        IsSaving = true;
        try
        {
            await OnSave.InvokeAsync(new NewTaskRequest(title, assignee, priority, dueDate, DefaultStatus));
        }
        finally
        {
            IsSaving = false;
        }
    }

    private async Task HandleCancel()
    {
        await OnCancel.InvokeAsync();
    }
}

@* A single Kanban column displaying its header, task cards, and optional add-task form *@

<div class="board-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="column-count">@Tasks.Count</span>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      IsMoving="movingTaskId == task.Id"
                      OnMoveLeft="HandleMoveLeft"
                      OnMoveRight="HandleMoveRight" />
        }
    </div>

    @if (showForm)
    {
        <AddTaskForm DefaultStatus="Status"
                     OnSave="HandleTaskSave"
                     OnCancel="() => { showForm = false; }" />
    }
    else
    {
        <button class="btn-add-task" @onclick="() => { showForm = true; }">+ Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = default!;
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<(int TaskId, string Direction)> OnMoveTask { get; set; }
    [Parameter] public EventCallback<AddTaskForm.NewTaskRequest> OnAddTask { get; set; }

    private bool showForm;
    private int? movingTaskId;

    private async Task HandleMoveLeft(int taskId)
    {
        movingTaskId = taskId;
        try
        {
            await OnMoveTask.InvokeAsync((taskId, "left"));
        }
        finally
        {
            movingTaskId = null;
        }
    }

    private async Task HandleMoveRight(int taskId)
    {
        movingTaskId = taskId;
        try
        {
            await OnMoveTask.InvokeAsync((taskId, "right"));
        }
        finally
        {
            movingTaskId = null;
        }
    }

    private async Task HandleTaskSave(AddTaskForm.NewTaskRequest request)
    {
        await OnAddTask.InvokeAsync(request);
        showForm = false;
    }
}

@* Search input that filters tasks by title *@

<div class="search-bar">
    <input type="text"
           placeholder="Search tasks by title..."
           value="@SearchTerm"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter] public string SearchTerm { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> SearchTermChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? string.Empty;
        await SearchTermChanged.InvokeAsync(value);
    }
}

