@* Inline form for creating a new task within a column *@

<div class="add-task-form">
    <input type="text" placeholder="Title" @bind="title" />
    <input type="text" placeholder="Assignee" @bind="assignee" />
    <select @bind="priority">
        <option value="High">High</option>
        <option value="Medium">Medium</option>
        <option value="Low">Low</option>
    </select>
    <input type="date" @bind="dueDate" />
    <div class="form-actions">
        <button class="btn-save" @onclick="HandleSave" disabled="@IsSaving">Save</button>
        <button class="btn-cancel" @onclick="HandleCancel" disabled="@IsSaving">Cancel</button>
    </div>
    @if (!string.IsNullOrEmpty(validationError))
    {
        <div class="form-error">@validationError</div>
    }
</div>

@code {
    [Parameter, EditorRequired] public string DefaultStatus { get; set; } = default!;
    [Parameter] public EventCallback<NewTaskRequest> OnSave { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);
    private bool IsSaving;
    private string? validationError;

    public record NewTaskRequest(string Title, string Assignee, string Priority, DateTime DueDate, string Status);

    private async Task HandleSave()
    {
        validationError = null;

        if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(assignee))
        {
            validationError = "Title and assignee are required.";
            return;
        }

        IsSaving = true;
        try
        {
            await OnSave.InvokeAsync(new NewTaskRequest(title, assignee, priority, dueDate, DefaultStatus));
        }
        finally
        {
            IsSaving = false;
        }
    }

    private async Task HandleCancel()
    {
        await OnCancel.InvokeAsync();
    }
}

