@* A single Kanban column displaying its header, task cards, and optional add-task form *@

<div class="board-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="column-count">@Tasks.Count</span>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      IsMoving="movingTaskId == task.Id"
                      OnMoveLeft="HandleMoveLeft"
                      OnMoveRight="HandleMoveRight" />
        }
    </div>

    @if (showForm)
    {
        <AddTaskForm DefaultStatus="Status"
                     OnSave="HandleTaskSave"
                     OnCancel="() => { showForm = false; }" />
    }
    else
    {
        <button class="btn-add-task" @onclick="() => { showForm = true; }">+ Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = default!;
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<(int TaskId, string Direction)> OnMoveTask { get; set; }
    [Parameter] public EventCallback<AddTaskForm.NewTaskRequest> OnAddTask { get; set; }

    private bool showForm;
    private int? movingTaskId;

    private async Task HandleMoveLeft(int taskId)
    {
        movingTaskId = taskId;
        try
        {
            await OnMoveTask.InvokeAsync((taskId, "left"));
        }
        finally
        {
            movingTaskId = null;
        }
    }

    private async Task HandleMoveRight(int taskId)
    {
        movingTaskId = taskId;
        try
        {
            await OnMoveTask.InvokeAsync((taskId, "right"));
        }
        finally
        {
            movingTaskId = null;
        }
    }

    private async Task HandleTaskSave(AddTaskForm.NewTaskRequest request)
    {
        await OnAddTask.InvokeAsync(request);
        showForm = false;
    }
}

